/* @lc app=leetcode id=3639 lang=kotlin */ class Solution { fun f(l: Long): Long = l * (l + 1) / 2 fun minTime(s: String, order: IntArray, k: Int): Int = s.length.toLong().let { n -> java.util.TreeSet<Int>().also { it.add(-1) }.also { it.add(s.length) }.let { ts -> LongArray(1) { f(n) }.let { free -> order.indices.firstOrNull { t -> order[t].let { p -> ts.lower(p)!!.let { lo -> ts.higher(p)!!.let { hi -> free.set(0, free[0] + f((p - lo - 1).toLong()) + f((hi - p - 1).toLong()) - f((hi - lo - 1).toLong())).also { ts.add(p) }.let { f(n) - free[0] >= k } } } } } ?: -1 } } } }